<script setup lang="ts">
import {computed,onMounted} from 'vue'
import {useRoute} from 'vue-router'
import {ArrowLeft,MapPin,ExternalLink,Store,Clock3,Coins,Utensils} from 'lucide-vue-next'
import DestinationActions from '../components/DestinationActions.vue'
import DetailMedia from '../components/DetailMedia.vue'
import DetailAsk from '../components/DetailAsk.vue'
import ExternalMap from '../components/ExternalMap.vue'
import {journey,loadJourney,localDate,clock,nameOf} from '../journey'
const route=useRoute(),vendor=computed(()=>route.path.startsWith('/vendor/')?journey.catalog.find(x=>x.record.kind==='vendor'&&x.record.fact_id===route.params.id):null)
const rawPlace=computed(()=>journey.catalog.find(x=>x.record.kind==='place'&&x.record.fact_id===(vendor.value?.record.place_id||route.params.id)))
const place=computed(()=>rawPlace.value?.record.superseded_by?journey.catalog.find(x=>x.record.kind==='place'&&x.record.fact_id===rawPlace.value!.record.superseded_by):rawPlace.value)
const pending=computed(()=>route.params.id==='pending'),merchant=computed(()=>pending.value||!!vendor.value||place.value?.record.place_type==='restaurant')
const opening=computed(()=>journey.catalog.find(x=>x.record.kind==='open_rule'&&x.record.place_id===place.value?.record.fact_id&&x.record.business_date===localDate()&&x.ready))
const vendorFacts=computed(()=>journey.catalog.find(x=>x.record.kind==='vendor'&&x.record.place_id===place.value?.record.fact_id))
const hours=computed(()=>place.value?.record.business_hours||vendorFacts.value?.record.business_hours||(opening.value?.record.opens_at&&opening.value.record.closes_at?clock(opening.value.record.opens_at)+'–'+clock(opening.value.record.closes_at):'待添加'))
const sources=computed(()=>journey.catalog.filter(x=>x.record.kind==='source'&&place.value?.record.source_ids?.includes(x.record.fact_id)&&x.record.url))
const supplies=computed(()=>{const ids=journey.catalog.filter(x=>x.record.kind==='vendor'&&x.record.place_id===place.value?.record.fact_id&&x.ready).map(x=>x.record.fact_id);return journey.catalog.filter(x=>x.record.kind==='supply'&&ids.includes(x.record.vendor_id||'')&&x.ready&&!x.record.is_demo)})
const kind=computed(()=>vendor.value?'vendor':place.value?.record.place_type==='poi'?'poi':'place')
const title=computed(()=>place.value?.record.name||'商家名称待添加')
onMounted(()=>loadJourney())
</script>
<template><div class="page place-detail-page editorial-detail"><RouterLink to="/" class="back-link"><ArrowLeft :size="16"/>返回发现</RouterLink><div v-if="journey.loading" class="state" role="status">正在查看地点资料…</div><template v-else-if="place||pending"><div class="place-cover-placeholder"><Store v-if="merchant" :size="48" :stroke-width="1"/><MapPin v-else :size="48" :stroke-width="1"/><span>实景照片待添加</span></div><header class="editorial-title"><span class="tiny-caption">{{merchant?'具体商家':'城市地点'}} · {{place?.record.planning_status==='reference'?'有来源的参考资料':place?.ready?'已有核验资料':'待添加'}}</span><h1>{{title}}</h1><p v-if="place?.record.description">{{place.record.description}}</p><p v-if="place?.record.parent_place_id">所属景区 · {{nameOf(place.record.parent_place_id)}}</p><DestinationActions v-if="place&&place.record.longitude!=null" :kind="kind" :id="String(route.params.id)" :name="title"/><small v-else-if="place" class="pending-caption">位置待补充，可先查看资料</small></header><dl class="detail-fact-grid"><div><dt><MapPin :size="16"/>详细地址</dt><dd>{{place?.record.address||'待添加'}}</dd></div><div><dt><Clock3 :size="16"/>营业时间</dt><dd>{{hours}}</dd></div><div><dt><Coins :size="16"/>参考人均</dt><dd>{{place?.record.price_band||vendorFacts?.record.price_band||'待添加'}}</dd></div><div><dt><ExternalLink :size="16"/>信息核验</dt><dd>{{place?.record.planning_status==='reference'?'已有资料，以现场信息为准':'来源与时间待添加'}}</dd></div></dl><section v-if="merchant" class="editorial-section"><div class="detail-section-title"><h2>在这家店品尝</h2><Utensils :size="20"/></div><p v-if="!supplies.length" class="content-pending">关联菜品与供应关系待添加</p><article v-for="s in supplies" :key="s.record.fact_id" class="info-item">{{nameOf(s.record.food_id)}}</article></section><DetailMedia :kind="kind" :id="String(route.params.id)" :name="title"/><section class="editorial-section"><h2>到店指引</h2><ExternalMap v-if="place?.record.address" :key="place.record.fact_id" :name="title" :address="place.record.address"/><div v-else class="content-pending"><MapPin :size="24"/>具体位置待添加</div></section><div class="place-sources"><a v-for="s in sources" :key="s.record.fact_id" :href="s.record.url" target="_blank" rel="noopener noreferrer">{{s.record.name}}<ExternalLink :size="13"/></a></div><DetailAsk v-if="place" :kind="kind" :id="String(route.params.id)" :name="title"/><p v-else class="pending-copy">添加真实商家资料后，可收藏、加入素材篮或询问小汴梁。</p></template><div v-else class="journey-empty"><h1>地点资料待添加</h1><button type="button" @click="loadJourney(true)">重试</button></div></div></template>
